local function __getSettings()
    local customSoundSettingsData = PlayerPrefsUtility.GetEncryptedString("customSoundSettings")
    local data = {}
    if string.isEmpty(customSoundSettingsData) then
        data = SoundDefaultConfig
    else
        data = table.deserialize(customSoundSettingsData)
        if isNull(data.Volume) then
            data["Volume"] = SoundDefaultConfig.Volume
        end
    end
    return data
end
local function __init()
    if not isInitial then
        ---获取初始设置的音量数据
        local data = __getSettings()
        local parameters = SoundParam(1, false, false)
        soundMgr:Initialize(parameters)
        soundMgr:RegisterSoundByType(CriWareCategory.BGM, SoundParam(data.Music.Switch == 0 and data.Music.Slider or 0, false, false))
        soundMgr:RegisterSoundByType(CriWareCategory.SE, SoundParam(data.Effect.Switch == 0 and data.Effect.Slider or 0, false, false))
        -- soundMgr:RegisterSoundByType(Constants.CriWareCategory.AMBIENCE, SoundParam(data.Effect.Switch == 0 and data.Effect.Slider or 0, true, false))
        soundMgr:RegisterSoundByType(CriWareCategory.VOICE, SoundParam(data.Volume.Switch == 0 and data.Volume.Slider or 0, false, false))
        soundMgr:RegisterSoundByType(CriWareCategory.VOICE_CAN_TIME_STRENTCH, SoundParam(data.Volume.Switch == 0 and data.Volume.Slider or 0, false, false))
        CriManaMovieMaterial.Volume = (data.Music.Switch == 0 and data.Music.Slider or 0)
        isInitial = true
    end
end

---ResetVolume
--- 重置音频音量的大小
---@param soundType number 音频类型
function CriWareUtils.ResetVolume(soundType)
    __init()
    local data = __getSettings()
    local volume = 0
    if soundType == Constants.CriWareCategory.VOICE then
        volume = data.Volume.Switch == 0 and data.Volume.Slider or 0
    elseif soundType == Constants.CriWareCategory.SE then
        volume = data.Effect.Switch == 0 and data.Effect.Slider or 0
    elseif soundType == Constants.CriWareCategory.BGM then
        volume = data.Music.Switch == 0 and data.Music.Slider or 0
    elseif soundType == Constants.CriWareCategory.VOICE_CAN_TIME_STRENTCH then
        volume = data.Volume.Switch == 0 and data.Volume.Slider or 0
    end
    CriWareUtils.SetVolume(soundType, volume)
end

---SetVolume
--- 设置音频音量的大小
---@param soundType number 音频类型
---@param volume number 音量大小
function CriWareUtils.SetVolume(soundType, volume)
    __init()
    if soundType == Constants.CriWareCategory.BGM then
        ---如果是设置背景音乐
        CriManaMovieMaterial.Volume = volume
    end
    local param = soundMgr:GetSoundParam(soundType)
    param.volume = checkNumber(volume)
    soundMgr:RegisterSoundByType(soundType, param)
end

