---PlayVoice
---播放音频的api
---@param sheetPath string @ sheet的相对路径
---@param cueName string @ cue名称
---@param go UnityEngine.GameObject @ 是否是3d对象类型 go为可选参数
---@return Engine.Lib.SoundSlice
function CriWareUtils.PlayVoice(sheetPath, cueName, go, canTimeStrentch2D)
    __init()
    sheetPath = CriWareUtils.AddI18NPath(sheetPath)
    -- print("[语音]",sheetPath,cueName,go)
    local criWareCategory = CriWareCategory.VOICE
    if isNotNull(canTimeStrentch2D) and canTimeStrentch2D == true then
        criWareCategory = CriWareCategory.VOICE_CAN_TIME_STRENTCH
    end
    -- print("[语音]",criWareCategory,sheetPath,cueName,go)
    return CriSoundMgr.Play(criWareCategory, sheetPath, cueName, go)
end

--- 给语音路径添加多语言的tag
---@param sheetPath any
function CriWareUtils.AddI18NPath(sheetPath)
    if SettingVoiceMgr == nil then
        SettingVoiceMgr = import("Game.UI.Setting.SettingVoiceMgr")
        SettingVoiceMgr:Init()
    end
    if SettingVoiceMgr:IsCurrentUseDefaultVoice() then
        return sheetPath
    end
    local list = string.split(sheetPath, "/")
    local i18nPath = SettingVoiceMgr:GetCurrentVoiceTag()
    local result = table.concat({list[1],i18nPath,list[2]}, "/")

    -- 如果I18N的语音文件不存在，那么回退到默认语音
    if CriWareUtils.IsAcbFileExists(result) then
        -- print(string.format("[i18n语音] %s %s", i18nPath, sheetPath))
        return result
    else
        -- print(string.format("[i18n语音] %s %s 不存在，回退到默认语言", i18nPath, sheetPath))
        return sheetPath
    end
end

function CriWareUtils.IsAcbFileExists(sheetPath)
    local acbPath = SoundSheet.AcbPath(sheetPath)
    if CriWareCommon.IsStreamingAssetsPath(acbPath) then
        acbPath = Path.Combine(CriWareCommon.streamingAssetsPath, acbPath)
    end
    -- print("[i18n语音] 文件检查 ", sheetPath, acbPath)
    return File.Exists(acbPath)
end

