--- 设置当前BGM的块索引
---@param index any
function CriWareUtils.CurrentBGMSetNextBlockIndex(index)
    if isNull(current_bgm_sound_slice) or isNull(index) then
        return -1
    end
    local soundSlice = current_bgm_sound_slice
    local playback = soundSlice:GetPlayback()
    local idx = playback:GetCurrentBlockIndex()
    if idx == -1 then
        local cueInfo = soundSlice.CueInfo
        local sheetPath = cueInfo.CueSheetPath
        local cueName = cueInfo.Cue
        printError(string.format("[BGM] %s  %s  没有块序列", sheetPath, cueName))
        return -1
    else
        local cueInfo = soundSlice.CueInfo
        local sheetPath = cueInfo.CueSheetPath
        local cueName = cueInfo.Cue

        local acb = CriAtom.GetAcb(sheetPath)
        local suc, cueInfo = acb:GetCueInfo(cueName)
        if index < cueInfo.numBlocks then
            playback:SetNextBlockIndex(index)
            print("[BGM] ", cueName, " set block index ", index)
            return 0
        else
            printError(string.format("[BGM] %s  %s  没找到块索引 %d", sheetPath, cueName, index))
            return -1
        end
    end
end

--- 获取当前BGM的块索引
function CriWareUtils.CurrentBGMGetCurrentBlockIndex()
    if isNull(current_bgm_sound_slice) then
        return -1
    end
    local soundSlice = current_bgm_sound_slice
    local playback = soundSlice:GetPlayback()
    return playback:GetCurrentBlockIndex()      -- 没有块的BGM会返回-1
end

