---PauseAll
---暂停所有音频
function CriWareUtils.StopAll(ignoreReleaseTime)
    __init()
    -- print("[声音] StopAll", CriWareUtils, debug.traceback())
    CriWareUtils.RecordBgm()
    CriSoundMgr.StopAll(checkBool(ignoreReleaseTime))
end

function CriWareUtils.Stop(sheetPath, cueName, soundType)
    __init()
    -- local slice = soundMgr:GetSoundSlice(CueInfo(cueName, sheetPath), soundType)
    -- CriSoundMgr.Stop(slice, true)
    -- print("[声音] Stop", CriWareUtils, sheetPath, cueName, debug.traceback())
    if sheetPath == current_bgm_sheet and cueName == current_bgm_cue then
        CriWareUtils.RecordBgm()
    end
    CriSoundMgr.Stop(CueInfo(cueName, sheetPath))
end

function CriWareUtils.StopById(soundId)
    if not soundId or string.isEmpty(soundId) then
        return
    end
    __init()
    local settingMgr = SettingMgr:GetInstance()
    local setting = settingMgr:GetSetting(AutoIds.IdSetting567, "SoundVo")
    ---@type SoundVo
    local data = setting:Get(soundId)
    if isTable(data) then
        -- print("[声音] StopById", data.cueName, debug.traceback())
        return CriWareUtils.Stop(data.sheetPath, data.cueName)
    end
end

function CriWareUtils.RecordBgm()
    if string.isEmpty(current_bgm_cue) or string.isEmpty(current_bgm_sheet) then
        return  -- 防止连续stopAll会吧lastBGM清空
    end
    last_bgm_sheet = current_bgm_sheet
    last_bgm_cue = current_bgm_cue
    current_bgm_sheet = ""
    current_bgm_cue = ""
    -- print("[声音] record bgm", CriWareUtils, last_bgm_sheet, last_bgm_cue, current_bgm_sheet, current_bgm_cue, debug.traceback())
end

